{
  "event_schema": {
    "additionalProperties": false,
    "properties": {
      "schema_version": {
        "const": "1.0",
        "default": "1.0",
        "title": "Schema Version",
        "type": "string"
      },
      "event_id": {
        "pattern": "^[a-zA-Z0-9][a-zA-Z0-9_.:-]{0,95}$",
        "title": "Event Id",
        "type": "string"
      },
      "journey_id": {
        "pattern": "^[a-zA-Z0-9][a-zA-Z0-9_.:-]{0,95}$",
        "title": "Journey Id",
        "type": "string"
      },
      "agent_id": {
        "pattern": "^[a-zA-Z0-9][a-zA-Z0-9_.:-]{0,95}$",
        "title": "Agent Id",
        "type": "string"
      },
      "merchant_id": {
        "pattern": "^[a-zA-Z0-9][a-zA-Z0-9_.:-]{0,95}$",
        "title": "Merchant Id",
        "type": "string"
      },
      "product": {
        "pattern": "^[a-zA-Z0-9][a-zA-Z0-9_.:-]{0,95}$",
        "title": "Product",
        "type": "string"
      },
      "domain": {
        "enum": [
          "digital_service",
          "physical_goods"
        ],
        "title": "Domain",
        "type": "string"
      },
      "stage": {
        "enum": [
          "intent",
          "quote",
          "checkout",
          "payment_authorized",
          "payment_settled",
          "fulfilled",
          "cancelled",
          "refunded",
          "failed"
        ],
        "title": "Stage",
        "type": "string"
      },
      "event_time": {
        "format": "date-time",
        "title": "Event Time",
        "type": "string"
      },
      "protocol": {
        "default": "first_party",
        "enum": [
          "first_party",
          "acp",
          "ucp",
          "ap2",
          "x402"
        ],
        "title": "Protocol",
        "type": "string"
      },
      "protocol_version": {
        "default": "1",
        "pattern": "^[a-zA-Z0-9][a-zA-Z0-9_.:-]{0,95}$",
        "title": "Protocol Version",
        "type": "string"
      },
      "category": {
        "default": "unspecified",
        "pattern": "^[a-zA-Z0-9][a-zA-Z0-9_.:-]{0,95}$",
        "title": "Category",
        "type": "string"
      },
      "buyer_type": {
        "default": "ai_agent",
        "enum": [
          "ai_agent",
          "human",
          "unknown"
        ],
        "title": "Buyer Type",
        "type": "string"
      },
      "item_id": {
        "anyOf": [
          {
            "pattern": "^[a-zA-Z0-9][a-zA-Z0-9_.:-]{0,95}$",
            "type": "string"
          },
          {
            "type": "null"
          }
        ],
        "default": null,
        "title": "Item Id"
      },
      "country": {
        "default": "ZZ",
        "pattern": "^[A-Z]{2}$",
        "title": "Country",
        "type": "string"
      },
      "currency": {
        "pattern": "^[A-Z]{3}$",
        "title": "Currency",
        "type": "string"
      },
      "amount_minor": {
        "anyOf": [
          {
            "maximum": 1000000000000000,
            "minimum": 0,
            "type": "integer"
          },
          {
            "type": "null"
          }
        ],
        "default": null,
        "title": "Amount Minor"
      },
      "quantity": {
        "default": 1,
        "maximum": 1000000,
        "minimum": 1,
        "title": "Quantity",
        "type": "integer"
      },
      "evidence_ref": {
        "anyOf": [
          {
            "pattern": "^[a-f0-9]{64}$",
            "type": "string"
          },
          {
            "type": "null"
          }
        ],
        "default": null,
        "title": "Evidence Ref"
      },
      "payment_ref": {
        "anyOf": [
          {
            "pattern": "^[a-f0-9]{64}$",
            "type": "string"
          },
          {
            "type": "null"
          }
        ],
        "default": null,
        "title": "Payment Ref"
      },
      "journey_closed": {
        "default": false,
        "title": "Journey Closed",
        "type": "boolean"
      },
      "agent_attestation_ref": {
        "anyOf": [
          {
            "pattern": "^[a-f0-9]{64}$",
            "type": "string"
          },
          {
            "type": "null"
          }
        ],
        "default": null,
        "title": "Agent Attestation Ref"
      },
      "test_event": {
        "default": false,
        "title": "Test Event",
        "type": "boolean"
      }
    },
    "required": [
      "event_id",
      "journey_id",
      "agent_id",
      "merchant_id",
      "product",
      "domain",
      "stage",
      "event_time",
      "currency"
    ],
    "title": "Event",
    "type": "object"
  },
  "endpoint": "/commerce/v1/events",
  "source_registration": "operator reviews contributor scope and separately assigns source capabilities",
  "delivery": "WakeClient with durable Outbox; immutable IDs and signed acceptance receipts",
  "provider_protocol_verification": false
}

